import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Memoh の概要","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/overview.md","filePath":"ja/guides/overview.md","lastUpdated":1792323081000}'),l={name:"ja/guides/overview.md"};function h(i,e,s,n,m,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="memoh-の概要" tabindex="-1">Memoh の概要 <a class="header-anchor" href="#memoh-の概要" aria-label="Permalink to &quot;Memoh の概要&quot;">​</a></h1><p>Memoh はすべての Bot に、それぞれ専用のクラウドコンピューターを与えます。本物のファイルシステムとターミナルを備えたワークスペース、画面を見ながら引き継ぎもできるデスクトップブラウザ、そしてセッションをまたいで引き継がれる長期メモリです。ノート PC を閉じても、Bot はそのまま働き続けます。</p><p>Bot との協働は、メッセージを送ることから始まります。Memoh アプリで話しかけることも、Telegram、Slack、Discord、Feishu、DingTalk、WeCom、WeChat、QQ、LINE に接続することもできます。どの入り口から入っても、相手は同じ Bot、同じメモリです。</p><p>始めるのに必要なのは、アプリをダウンロードして Memoh Cloud にサインインすることだけです。ホスト済みモデル（DeepSeek、Kimi、GPT、Claude など）はそのまま使えます。自分の API Key やモデルサービスを使いたい場合は <a href="./quick-start.html#自分のモデルを使う-byok">BYOK</a> を参照してください。</p><h2 id="memoh-は何が違うのか" tabindex="-1">Memoh は何が違うのか <a class="header-anchor" href="#memoh-は何が違うのか" aria-label="Permalink to &quot;Memoh は何が違うのか&quot;">​</a></h2><ul><li><strong>使い捨てのサンドボックスではなく、本物のコンピューター。</strong> 書き込んだファイルもインストールしたランタイムも <a href="./container.html">ワークスペース</a> に残ります。月曜日に用意したものは、金曜日にもそのまま使えます。</li><li><strong>目に見える画面。</strong> Bot は可視デスクトップ上で本物のブラウザを操作します。ログインや CAPTCHA にぶつかったら、あなたが <a href="./browser-computer-use.html">キーボードとマウスを引き継いで</a> その手順を済ませ、また Bot に操作を返せます。</li><li><strong>覚えている。</strong> <a href="./memory.html">長期メモリ</a> はセッションとチャネルをまたいで働きます。一度直してもらった好みを、もう一度言い直す必要はありません。</li><li><strong>あなたがいなくても動いている。</strong> <a href="./schedule.html">スケジュールタスク</a> は cron で発火し、接続済みのチャネルに結果を届けます。時間どおりにチェックし、変化があったときだけ報告します。</li><li><strong>自分のコーディングエージェントを持ち込める。</strong> <a href="./acp.html">ACP</a> 経由で Claude Code や Codex を同じワークスペースに入れて、自分のサブスクリプションで使えます。</li></ul><h2 id="_1-つの-bot-に-1-つの仕事" tabindex="-1">1 つの Bot に 1 つの仕事 <a class="header-anchor" href="#_1-つの-bot-に-1-つの仕事" aria-label="Permalink to &quot;1 つの Bot に 1 つの仕事&quot;">​</a></h2><p>どの Bot も専用のワークスペース、メモリ、チャネル、権限境界を持ち、互いの中身は見えません。仕事が本当に別々の役割に分かれるときは、1 つの Bot に積み増すのではなく、もう 1 つ Bot を作ってください。誰が Bot と話せるか、誰がファイルを読み書きできるか、誰がコマンドを実行できるかは、<a href="./access.html">アクセス制御</a> でレベルごとに付与します。必要なレベルだけを与えてください。</p><h2 id="最初のタスクの渡し方" tabindex="-1">最初のタスクの渡し方 <a class="header-anchor" href="#最初のタスクの渡し方" aria-label="Permalink to &quot;最初のタスクの渡し方&quot;">​</a></h2><p>毎週手作業でこなしている小さな仕事を 1 つ選び、結果・ソース・境界をはっきり伝えます。</p><blockquote><p>毎週金曜 17:00 に、今週私が送ったリンクとファイルを週報にまとめてください。テーマごとにグループ化して、1 件につき 1 行で。ワークスペースに保存し、要約をこの会話に投稿してください。まとめるのは私が送った内容だけにして、誰にも外部へ送らないでください。</p></blockquote><p>Bot は自分でスケジュールタスクを登録し、毎週届けてくれます。まずは読み取り専用の仕事から始め、成果物を何度か確認してから、書き込みや実行の権限を少しずつ広げましょう。</p><h2 id="よくある質問" tabindex="-1">よくある質問 <a class="header-anchor" href="#よくある質問" aria-label="Permalink to &quot;よくある質問&quot;">​</a></h2><p><strong>自分のコンピューターの電源を切っても動き続けますか？</strong></p><p>はい。Bot はクラウドのワークスペースで動いているため、スケジュールタスクは通常どおり発火し、チャネルのメッセージにも通常どおり返信します。</p><p><strong>Bot はいくつ作れますか？</strong></p><p>サブスクリプションプランによります。各 Bot は独立していて、専用のワークスペース・メモリ・権限を持ち、1 つ削除しても他には影響しません。</p><p><strong>自分のファイルはどこに置かれますか？</strong></p><p>その Bot の隔離されたコンテナワークスペース（<code>/data</code>）にあります。セッションをまたいで保持され、<a href="./files.html">ファイル</a> からいつでも閲覧・編集できます。</p><p><strong>自分のモデルを使えますか？</strong></p><p>使えます。モデルプロバイダーに自分の API Key を追加してください（<a href="./quick-start.html#自分のモデルを使う-byok">BYOK</a> を参照）。コーディングエージェントは、Bot の <strong>エージェント</strong> タブで自分の Claude Code / Codex サブスクリプションにサインインします。</p><p><strong>サブスクリプションや課金の質問はどこで聞けますか？</strong></p><p><a href="https://memoh.ai/help" target="_blank" rel="noreferrer">ヘルプセンター</a> へ。プラン、credits、アカウントの質問に加えて、Memoh チームへの連絡窓口もあります。</p><h2 id="次のステップ" tabindex="-1">次のステップ <a class="header-anchor" href="#次のステップ" aria-label="Permalink to &quot;次のステップ&quot;">​</a></h2><ul><li><a href="./quick-start.html">クイックスタート</a> — アプリのインストールからチャットプラットフォームへの接続まで、約 15 分。</li><li><a href="./working-with-bots.html">Bot</a> — Bot をタブごとに設定します。</li><li><a href="./../integrations/channels/">チャネル</a> — 各チャットプラットフォームの接続方法。</li><li><a href="https://memoh.ai/help" target="_blank" rel="noreferrer">ヘルプセンター</a> — サブスクリプション、請求、アカウントの質問。</li></ul>',25)])])}const u=a(l,[["render",h]]);export{c as __pageData,u as default};
